package com.healthcare.portal.service;
import com.healthcare.portal.entity.Payment; import org.apache.pdfbox.pdmodel.PDDocument; import org.apache.pdfbox.pdmodel.PDPage; import org.apache.pdfbox.pdmodel.PDPageContentStream; import org.apache.pdfbox.pdmodel.font.PDType1Font; import org.apache.pdfbox.pdmodel.font.Standard14Fonts; import org.springframework.stereotype.Service; import java.io.ByteArrayOutputStream;
@Service public class PdfInvoiceService { public byte[] invoice(Payment p){ try(PDDocument doc=new PDDocument()){ PDPage page=new PDPage(); doc.addPage(page); try(PDPageContentStream c=new PDPageContentStream(doc,page)){ c.beginText(); c.setFont(new PDType1Font(Standard14Fonts.FontName.HELVETICA_BOLD),16); c.newLineAtOffset(60,730); c.showText("HEALTHCARE PORTAL - PAYMENT INVOICE"); c.setFont(new PDType1Font(Standard14Fonts.FontName.HELVETICA),11); c.newLineAtOffset(0,-35); c.showText("Order ID: "+p.getRazorpayOrderId()); c.newLineAtOffset(0,-20); c.showText("Payment ID: "+String.valueOf(p.getRazorpayPaymentId())); c.newLineAtOffset(0,-20); c.showText("Amount: "+p.getAmount()); c.newLineAtOffset(0,-20); c.showText("Status: "+p.getStatus()); c.endText(); } ByteArrayOutputStream out=new ByteArrayOutputStream(); doc.save(out); return out.toByteArray(); }catch(Exception e){throw new IllegalStateException("Unable to generate invoice",e);} } }